/* ================= MATRIX OCEAN VISUALIZER ================= */
const Viz = (() => {
  'use strict';
  const canvas  = $('#vizCanvas');
  const ctx     = canvas.getContext('2d', { alpha: false });
  const statsEl = $('#vizStats');
  const vizEl   = $('#viz');
  const bloom   = document.createElement('canvas');
  const bctx    = bloom.getContext('2d');
  const reduced = !!(window.matchMedia && matchMedia('(prefers-reduced-motion: reduce)').matches);

  /* ---- color helpers ---- */
  function hexToRgb(hex){
    hex = String(hex).trim().replace('#','');
    if (hex.length === 3) hex = hex.split('').map(c => c + c).join('');
    if (hex.length < 6) return null;
    const n = parseInt(hex.slice(0,6), 16);
    if (isNaN(n)) return null;
    return [(n>>16)&255, (n>>8)&255, n&255];
  }
  function mix(c1, c2, t){ return c1.map((v,i) => Math.round(v + (c2[i]-v)*t)); }
  const rgba = (c, a) => a==null ? 'rgb(' + c.join(',') + ')' : 'rgba(' + c.join(',') + ',' + a + ')';

  /* ---- tunables ---- */
  const CAM_H=7, NEAR=2.2, FAR=85, CELL=0.7, FOCAL=1.12, SPEED=7;
  const FONT_STACK = 'ui-monospace, Menlo, Consolas, "Courier New", monospace';
  const SPRITE_PX=96, SPRITE_ASPECT=0.62;
  const SPRITE_W=Math.ceil(SPRITE_PX*SPRITE_ASPECT)+2, SPRITE_H=SPRITE_PX+2;
  const RAIN_TRAIL=12;
  const RAIN_FADE=[0.45,0.28,0.19,0.13,0.09,0.07,0.055,0.045,0.035,0.028,0.022,0.018];
  const RIPPLES_MAX=6;

  function bakeSprite(ch, color){
    const c=document.createElement('canvas');
    c.width=SPRITE_W; c.height=SPRITE_H;
    const g=c.getContext('2d');
    g.font=SPRITE_PX+'px '+FONT_STACK;
    g.textAlign='center'; g.textBaseline='middle';
    g.fillStyle=color;
    g.fillText(ch, SPRITE_W/2, SPRITE_H/2);
    return c;
  }

  let accent=[0,255,65], mid=[0,212,58], hi=[234,255,230];
  const SPRITES={ '0':[], '1':[] };
  function applyColor(){
    const raw = getComputedStyle(document.documentElement).getPropertyValue('--accent').trim();
    const parsed = hexToRgb(raw);
    if (parsed) accent = parsed;
    const white=[255,255,255], black=[0,0,0];
    mid = mix(accent, black, 0.28);
    hi  = mix(accent, white, 0.72);
    vizEl.style.setProperty('--mx', rgba(accent));
    vizEl.style.setProperty('--mx-glow', rgba(accent,0.55));
    vizEl.style.setProperty('--mx-soft', rgba(accent,0.55));
    SPRITES['0']=[bakeSprite('0', rgba(accent)), bakeSprite('0', rgba(mid))];
    SPRITES['1']=[bakeSprite('1', rgba(accent)), bakeSprite('1', rgba(mid))];
  }

  /* ---- state ---- */
  let W=0,H=0,DPR=1,cx=0,horizonY=0,f=0;
  let t=0,last=performance.now();
  let camZ=0,camX=0,yaw=0,cosYaw=1,sinYaw=0;
  let mouseTX=0,mouseNX=0;
  let quality=1, far=FAR, glyphCount=0;
  const ripples=[];
  let open=false, raf=0;

  function hash2(a,b,k){ const s=Math.sin(a*127.1+b*311.7+k*74.7)*43758.5453123; return s-Math.floor(s); }

  function resize(){
    DPR=Math.min(window.devicePixelRatio||1,2);
    W=window.innerWidth; H=window.innerHeight;
    canvas.width=Math.max(2,Math.round(W*DPR));
    canvas.height=Math.max(2,Math.round(H*DPR));
    ctx.setTransform(DPR,0,0,DPR,0,0);
    cx=W/2; horizonY=H/3; f=H*FOCAL;
    bloom.width=Math.max(2,(W/4)|0);
    bloom.height=Math.max(2,(H/4)|0);
  }

  function oceanHeight(x,z,time){
    let h=0;
    h+=1.35*Math.sin(x*0.16+Math.sin(z*0.11)*1.3+time*0.70);
    h+=1.10*Math.sin(z*0.13-time*0.55);
    h+=0.75*Math.sin((x+z)*0.075+time*0.40);
    h+=0.45*Math.sin(x*0.05-z*0.09+time*0.90);
    for(let n=0;n<ripples.length;n++){
      const r=ripples[n], dx=x-r.x, dz=z-r.z, d=Math.sqrt(dx*dx+dz*dz), age=time-r.t0;
      h+=2.4*Math.sin(d*0.35-age*5.2)*Math.exp(-d*0.055)*Math.exp(-age*1.1);
    }
    return h;
  }

  function drawRain(){
    const step=10, cols=Math.ceil(W/step);
    ctx.font='7px '+FONT_STACK;
    ctx.textAlign='center'; ctx.textBaseline='middle';
    for(let k=0;k<cols;k++){
      const sp=45+hash2(k,3,1)*110, off=hash2(k,7,2)*900;
      const headY=((t*sp+off)%(horizonY+60))-30;
      const x=k*step+hash2(k,1,4)*4;
      for(let m=0;m<RAIN_TRAIL;m++){
        const y=headY-m*5;
        if(y<8||y>horizonY-3) continue;
        const hFade=Math.min(1,(horizonY-y)/46+0.25);
        const a=RAIN_FADE[m]*hFade;
        if(a<0.01) continue;
        ctx.globalAlpha=a;
        ctx.fillStyle = m===0 ? rgba(hi) : rgba(accent);
        ctx.fillText(hash2(k,m*13,Math.floor(t*5))<0.5?'1':'0', x, y);
      }
    }
    ctx.globalAlpha=1;
  }

  function drawHorizon(){
    const b = (typeof breathLevel==='number') ? breathLevel : 0.5;
    const a = 0.09*(0.55 + b*0.9);
    const g=ctx.createLinearGradient(0,horizonY-70,0,horizonY+70);
    g.addColorStop(0,   rgba(accent,0));
    g.addColorStop(0.5, rgba(accent,a));
    g.addColorStop(1,   rgba(accent,0));
    ctx.fillStyle=g;
    ctx.fillRect(0,horizonY-70,W,140);
  }

  function drawOcean(){
    glyphCount=0;
    const b=(typeof breathLevel==='number')?breathLevel:0.5;
    const ampMul=0.72 + b*0.6;
    const hwPix=W*0.5;
    const wxR=hwPix*cosYaw + f*sinYaw, wzR=f*cosYaw - hwPix*sinYaw;
    const wxL=-hwPix*cosYaw + f*sinYaw, wzL=f*cosYaw + hwPix*sinYaw;
    const jMax=Math.floor((camZ+far)/CELL);
    const jMin=Math.max(0,Math.ceil((camZ+NEAR)/CELL));
    for(let j=jMax;j>=jMin;j--){
      const wz=j*CELL, rzApprox=wz-camZ;
      if(rzApprox<NEAR) continue;
      let xMin=camX+rzApprox*(wxL/wzL), xMax=camX+rzApprox*(wxR/wzR);
      if(xMin>xMax){const tmp=xMin;xMin=xMax;xMax=tmp;}
      const iMin=Math.ceil((xMin-2)/CELL), iMax=Math.floor((xMax+2)/CELL);
      for(let i=iMin;i<=iMax;i++){
        const wx=i*CELL, dx=wx-camX, dz=wz-camZ;
        const rx=dx*cosYaw - dz*sinYaw, rz=dx*sinYaw + dz*cosYaw;
        if(rz<NEAR) continue;
        const sc=f/rz, size=CELL*sc;
        if(size<1.6) continue;
        const sx=cx+rx*sc;
        if(sx<-size||sx>W+size) continue;
        const h=oceanHeight(wx,wz,t)*ampMul;
        const sy=horizonY-(h+0.18-CAM_H)*sc;
        if(sy>H+size||sy<-size) continue;
        let a=1-rz/far;
        if(a<=0) continue;
        a=Math.pow(a,1.5);
        a+=(h+1.2)*0.05;
        if(a>0.95) a=0.95;
        if(a<0.03) continue;
        const ch=hash2(i,j,Math.floor(t*0.9)+i*17+j*31)<0.52?'1':'0';
        const fl=hash2(i,j,Math.floor(t*3.3)+5);
        const ci= fl>0.82 ? 1 : 0;
        const gw=size*SPRITE_ASPECT;
        ctx.globalAlpha=a;
        ctx.drawImage(SPRITES[ch][ci], sx-gw/2, sy-size/2, gw, size);
        glyphCount++;
      }
    }
    ctx.globalAlpha=1;
  }

  function drawBloom(){
    if(quality<0.55) return;
    bctx.clearRect(0,0,bloom.width,bloom.height);
    bctx.filter='blur(2px)';
    bctx.drawImage(canvas,0,0,bloom.width,bloom.height);
    bctx.filter='none';
    ctx.save();
    ctx.globalCompositeOperation='lighter';
    ctx.globalAlpha=0.45;
    ctx.drawImage(bloom,0,0,W,H);
    ctx.restore();
  }

  function applyQuality(){ far=FAR*(0.5+0.5*quality); }
  applyQuality();

  let acc=0,frames=0,fps=60,statTimer=0;
  function loop(now){
    if(!open) return;
    raf=requestAnimationFrame(loop);
    let dt=(now-last)/1000; last=now;
    if(dt<=0) return;
    if(dt>0.05) dt=0.05;
    t += reduced ? dt*0.3 : dt;
    for(let n=ripples.length-1;n>=0;n--){ if(t-ripples[n].t0>9) ripples.splice(n,1); }
    const b=(typeof breathLevel==='number')?breathLevel:0.5;
    mouseNX += (mouseTX-mouseNX)*Math.min(1,dt*3);
    const sway = reduced ? 0 : 0.028*Math.sin(t*0.21);
    yaw = mouseNX*0.10 + sway;
    cosYaw=Math.cos(yaw); sinYaw=Math.sin(yaw);
    const speedNow = SPEED*(0.5 + b*0.85);
    camZ += (reduced?0:speedNow)*dt;
    camX  = mouseNX*2.5 + (reduced?0:1.8*Math.sin(t*0.15));
    acc+=dt; frames++;
    if(acc>=0.5){
      fps=Math.round(frames/acc);
      statTimer+=acc;
      if(fps<30&&quality>0.45){ quality=Math.max(0.45,quality-0.15); applyQuality(); }
      else if(fps>55&&quality<1){ quality=Math.min(1,quality+0.1); applyQuality(); }
      acc=0; frames=0;
      if(statTimer>=0.5){ statTimer=0; statsEl.textContent='glyphs '+glyphCount+' · fps '+fps; }
    }
    ctx.fillStyle='#000';
    ctx.fillRect(0,0,W,H);
    drawRain();
    drawHorizon();
    drawOcean();
    drawBloom();
  }

  window.addEventListener('resize', () => { if(open) resize(); });
  window.addEventListener('pointermove', e => { mouseTX=(e.clientX/Math.max(1,W))*2-1; }, {passive:true});
  canvas.addEventListener('pointerdown', e => {
    const d=55;
    ripples.push({ x:camX+(e.clientX-cx)*d/f, z:camZ+d, t0:t });
    if(ripples.length>RIPPLES_MAX) ripples.shift();
  });

  function openFn(){
    if(open) return;
    open=true;
    vizEl.classList.add('open');
    applyColor();
    resize();
    last=performance.now();
    raf=requestAnimationFrame(loop);
  }
  function closeFn(){
    if(!open) return;
    open=false;
    cancelAnimationFrame(raf);
    vizEl.classList.remove('open');
  }

  return { open:openFn, close:closeFn, isOpen:()=>open, recolor:applyColor };
})();
